:root {
  --bg: #1b1b2f;
  --card: #26264a;
  --ink: #f2f2ff;
  --muted: #a5a5d0;
  --accent: #ffcc00;
  --accent-2: #ff5d8f;
  --border: #3d3d6b;
  --shadow: #0f0f1e;
  --font: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background:
    repeating-linear-gradient(0deg, transparent 0 31px, rgba(255,255,255,0.03) 31px 32px),
    repeating-linear-gradient(90deg, transparent 0 31px, rgba(255,255,255,0.03) 31px 32px),
    var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 24px;
  box-shadow:
    0 0 0 4px var(--shadow),
    8px 8px 0 0 var(--accent-2);
}

.title {
  margin: 0 0 20px;
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-align: center;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--shadow);
}

.field {
  margin: 0 0 20px;
  border: 0;
  padding: 0;
}

label,
legend {
  display: block;
  margin-bottom: 8px;
  font-size: 16px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.input-wrap {
  display: flex;
  align-items: center;
  background: var(--bg);
  border: 3px solid var(--border);
}

.input-wrap:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 204, 0, 0.3);
}

.prefix {
  padding: 0 12px;
  color: var(--accent);
  font-size: 20px;
}

input {
  flex: 1;
  width: 100%;
  min-width: 0;
  padding: 12px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--ink);
  font-family: inherit;
  font-size: 20px;
}

.input-wrap input {
  border: 0;
  padding-left: 0;
}

input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 204, 0, 0.3);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.tip-btn {
  padding: 12px 4px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--ink);
  font-family: inherit;
  font-size: 18px;
  cursor: pointer;
  transition: transform 0.05s, background 0.1s, border-color 0.1s;
}

.tip-btn:hover {
  border-color: var(--accent);
  background: #2f2f5a;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translateY(2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg);
  font-weight: bold;
  box-shadow: inset 0 -4px 0 rgba(0,0,0,0.25);
}

.results {
  margin-top: 8px;
  padding: 16px;
  background: var(--bg);
  border: 3px solid var(--border);
  display: grid;
  gap: 8px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}

.result-label {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 14px;
}

.result-value {
  font-size: 22px;
  color: var(--accent);
  font-weight: bold;
}

.result-row.total .result-value {
  font-size: 26px;
  color: var(--accent-2);
}

.hint {
  margin: 12px 0 0;
  min-height: 1.5em;
  font-size: 14px;
  color: var(--accent-2);
  text-align: center;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .title {
    font-size: 24px;
  }
  .result-value {
    font-size: 20px;
  }
  .result-row.total .result-value {
    font-size: 22px;
  }
}

(function () {
  "use strict";

  var billInput = document.getElementById("bill");
  var peopleInput = document.getElementById("people");
  var tipOutput = document.getElementById("tip");
  var totalOutput = document.getElementById("total");
  var hint = document.getElementById("hint");
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll(".tip-btn"));

  var tipPercent = 15;

  function formatMoney(value) {
    if (!isFinite(value) || value < 0) value = 0;
    return "$" + value.toFixed(2);
  }

  function parseNumber(input, fallback) {
    var raw = input.value.trim();
    if (raw === "") return fallback;
    var n = Number(raw);
    return isFinite(n) ? n : fallback;
  }

  function calculate() {
    var bill = parseNumber(billInput, 0);
    var people = parseNumber(peopleInput, 1);
    var messages = [];

    if (bill < 0) {
      bill = 0;
      messages.push("Bill cannot be negative.");
    }

    if (people < 1) {
      people = 1;
      messages.push("People set to 1 (minimum).");
    } else if (people % 1 !== 0) {
      people = Math.floor(people);
      messages.push("People rounded down to " + people + ".");
    }

    var tipAmount = bill * (tipPercent / 100);
    var totalPerPerson = (bill + tipAmount) / people;

    tipOutput.textContent = formatMoney(tipAmount);
    totalOutput.textContent = formatMoney(totalPerPerson);
    hint.textContent = messages.join(" ");
  }

  function selectTip(button) {
    tipPercent = Number(button.getAttribute("data-tip"));
    tipButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", btn === button ? "true" : "false");
    });
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      selectTip(button);
    });
  });

  billInput.addEventListener("input", calculate);
  peopleInput.addEventListener("input", calculate);

  calculate();
})();
